// Verificador de linealizabilidad para un registro (valor inicial 0) por fuerza bruta.
// Cada operación: quién, tipo, valor, inicio y fin (en ms, relojes ideales de un observador externo).
function probar(nombre, ops) {
  let hallado = null;
  const n = ops.length, usados = new Array(n).fill(false), orden = [];
  (function ir(valor) {
    if (hallado) return;
    if (orden.length === n) { hallado = orden.slice(); return; }
    for (let i = 0; i < n && !hallado; i++) {
      if (usados[i]) continue;
      const o = ops[i];
      if (ops.some((p, j) => !usados[j] && j !== i && p.fin < o.ini)) continue;
      if (o.tipo === "R" && o.v !== valor) continue;
      usados[i] = true; orden.push(o.q);
      ir(o.tipo === "W" ? o.v : valor);
      usados[i] = false; orden.pop();
    }
  })(0);
  console.log(nombre.padEnd(34), hallado ? "LINEALIZABLE, orden posible: " + hallado.join(" > ") : "NO es linealizable");
}
const W = (q, v, ini, fin) => ({ q, tipo: "W", v, ini, fin });
const R = (q, v, ini, fin) => ({ q, tipo: "R", v, ini, fin });
probar("1) lectura que se solapa con W(1)", [W("Ana escribe 1", 1, 0, 10), R("Beto lee 0", 0, 5, 15)]);
probar("2) lee viejo después de terminar W", [W("Ana escribe 1", 1, 0, 10), R("Beto lee 0", 0, 20, 30)]);
probar("3) ve el 1 y después vuelve al 0", [W("Ana escribe 1", 1, 0, 100), R("Beto lee 1", 1, 10, 20), R("Beto lee 0", 0, 30, 40)]);
probar("4) ve el 1 y sigue viendo el 1", [W("Ana escribe 1", 1, 0, 100), R("Beto lee 0", 0, 10, 20), R("Beto lee 1", 1, 30, 40)]);

// Latencia de escritura según cuántas réplicas esperás (datos inventados de ida y vuelta, en ms).
const rtt = { "Córdoba": 18, "San Pablo": 45, "Virginia": 140 }; // ESTIMACIÓN inventada, del orden de lo que se mide entre esas zonas
const local = 1; // lo que tarda el líder (en Buenos Aires) en escribir en su disco
const f = Object.values(rtt).sort((a, b) => a - b);
console.log("Latencia de una escritura en el líder de Buenos Aires, según a cuántas réplicas esperás:");
console.log("  solo el líder escribió (asíncrona):        ", local, "ms");
console.log("  esperás a 1 réplica (la de Córdoba):      ", local + f[0], "ms");
console.log("  esperás a 2 réplicas (+ San Pablo):       ", local + f[1], "ms");
console.log("  esperás a las 3 réplicas (+ Virginia):   ", local + f[2], "ms");
// Con replicación asíncrona, ¿qué fracción de lecturas a una réplica ve un dato viejo?
function prng(s) { return () => (s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32; }
const rnd = prng(2026);
const lag = 50; // ms de demora de replicación (inventado)
let viejas = 0, N = 100000;
for (let i = 0; i < N; i++) { const despues = rnd() * 1000; if (despues < lag) viejas++; } // una escritura por segundo; lectura en un instante al azar
console.log(`\nLectura en la réplica con ${lag} ms de demora, una escritura por segundo:`, (100 * viejas / N).toFixed(1) + "% de lecturas con el dato anterior");

// Dos réplicas de un depósito (BA y COR) con el stock de un artículo. Una partición entre t=2 y t=7.
const enParticion = (t) => t >= 2 && t < 7;
function simular(modo) {
  const r = { BA: { v: 10, vec: { BA: 0, COR: 0 }, sib: [] }, COR: { v: 10, vec: { BA: 0, COR: 0 }, sib: [] } };
  const otro = (x) => (x === "BA" ? "COR" : "BA");
  let atendidas = 0, rechazadas = 0;
  const log = (t, s) => console.log(`t=${t}  ${s}`);
  function escribir(t, nodo, nuevo, hora) {
    if (modo === "CP" && enParticion(t)) { rechazadas++; return log(t, `${nodo}: escribir ${nuevo} RECHAZADO (no alcanza a la otra réplica)`); }
    const a = r[nodo], b = r[otro(nodo)];
    a.v = nuevo; a.vec[nodo]++; a.hora = hora; atendidas++;
    if (!enParticion(t)) { b.v = nuevo; b.vec = { ...a.vec }; b.hora = hora; }
    log(t, `${nodo}: stock := ${nuevo}   vector ${JSON.stringify(a.vec)}`);
  }
  function leer(t, nodo) {
    if (modo === "CP" && enParticion(t)) { rechazadas++; return log(t, `${nodo}: leer RECHAZADO`); }
    atendidas++; log(t, `${nodo}: lee ${r[nodo].v}`);
  }
  escribir(1, "BA", 10, 100);
  escribir(3, "BA", 8, 300);   // BA vende 2
  escribir(4, "COR", 7, 400);  // COR vende 3 (parte de 10, no vio la venta de BA)
  leer(5, "BA"); leer(5, "COR");
  // se arregla la red en t=7: reconciliación
  const A = r.BA, C = r.COR;
  const concurr = Object.keys(A.vec).some((k) => A.vec[k] > C.vec[k]) && Object.keys(A.vec).some((k) => A.vec[k] < C.vec[k]);
  if (modo === "AP") {
    log(7, `red repuesta. BA ${JSON.stringify(A.vec)} vs COR ${JSON.stringify(C.vec)} -> ${concurr ? "CONCURRENTES: hay conflicto" : "uno es posterior"}`);
    const lww = A.hora > C.hora ? A.v : C.v;
    log(7, `  si se resuelve por «última escritura gana» (hora de pared): stock = ${lww}`);
    log(7, `  si se conservan las dos versiones y se suman las ventas (-2, -3): stock = ${10 - 2 - 3}`);
  } else log(7, `red repuesta. Nada que reconciliar: stock = ${A.v} en las dos`);
  console.log(`  -> atendidas ${atendidas}, rechazadas ${rechazadas}\n`);
}
console.log("=== Elige consistencia (CP) ==="); simular("CP");
console.log("=== Elige disponibilidad (AP) ==="); simular("AP");
